<template><div><div class="admin-page-head"><div><h1>Туры</h1><p>Все предложения, которые сейчас отдаёт поисковый слой Trove.</p></div><span class="pill">{{ data?.total ?? data?.items?.length ?? 0 }} результатов</span></div><div class="filters"><input v-model="q.search" class="input" placeholder="Отель, страна, направление…" @keyup.enter="load"><input v-model="q.destination" class="input" placeholder="Направление"><input v-model="q.priceFrom" class="input" type="number" placeholder="Цена от"><input v-model="q.priceTo" class="input" type="number" placeholder="Цена до"><select v-model="q.sort" class="select"><option value="recommended">Рекомендуемые</option><option value="price">Цена</option><option value="rating">Рейтинг</option></select><button class="btn primary" @click="load">Фильтровать</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Тур</th><th>Направление</th><th>Отель</th><th>Рейтинг</th><th>Цена</th><th>Поставщик</th></tr></thead><tbody><tr v-for="t in items" :key="t.id"><td><NuxtLink class="tour-link" :to="`/admin/tours/${t.provider || t.providerId}/${t.id}`"><b>{{ t.title||t.name }}</b></NuxtLink><div class="muted">{{ t.providerOfferId || t.id }}</div></td><td>{{ t.destination||t.country||'—' }}</td><td>{{ t.hotel||'—' }}</td><td>{{ t.rating||'—' }}</td><td><b>{{ money(t.price) }}</b></td><td><span class="pill" :class="t.adminActive === false ? 'warn' : (t.adminFeatured ? 'success' : '')">{{ t.adminFeatured ? 'Featured' : (t.providerId||t.provider?.id||t.provider||'—') }}</span></td></tr></tbody></table><div v-if="!items.length" class="empty">По вашему фильтру туров не найдено.</div></div></div></template>
<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'});const api=useApi();const q=reactive({search:'',destination:'',priceFrom:'',priceTo:'',sort:'recommended'});const data=ref<any>(null);const load=async()=>{data.value=await api('/api/admin/tours',{query:q})};await load();const items=computed(()=>data.value?.items||data.value?.results||[]);const money=(v:number)=>new Intl.NumberFormat('ru-RU').format(Number(v||0))+' ₽'
</script>
